    XrGraphicsRequirementsOpenGLESKHR req;

    XrGraphicsBindingOpenGLESAndroidKHR bind;
    XrSessionCreateInfo                 create;
    XrReferenceSpaceCreateInfo          space;

    XrReferenceSpaceType *types = NULL;
    uint32_t              type_count = 0, i;
    XrReferenceSpaceType  chosen = XR_REFERENCE_SPACE_TYPE_LOCAL;

    /*
     * Take the EGL triple from the context SDL already created rather than
     * making one of our own. This keeps the SDL_GL_GetProcAddress ordering
     * that gl4es was initialized with in share/video.c intact.
     */

