    EGLContext ctx = eglGetCurrentContext();
    EGLConfig  cfg = NULL;
    EGLint     cfg_id = 0, n = 0;

    if (dpy == EGL_NO_DISPLAY || ctx == EGL_NO_CONTEXT)
    {
        log_printf("HMD: no current EGL context to bind\n");
        return 0;
    }

    if (!eglQueryContext(dpy, ctx, EGL_CONFIG_ID, &cfg_id))
    {
        log_printf("HMD: eglQueryContext(EGL_CONFIG_ID) failed\n");
        return 0;
    }

    {
        const EGLint attrs[] = { EGL_CONFIG_ID, cfg_id, EGL_NONE };

        if (!eglChooseConfig(dpy, attrs, &cfg, 1, &n) || n != 1)
        {
            log_printf("HMD: could not recover EGLConfig %d\n", (int) cfg_id);
            return 0;
        }
    }

    /* The runtime requires this query before session creation. */

    XR_TRY(xrGetInstanceProcAddr(xr_instance,
                                 "xrGetOpenGLESGraphicsRequirementsKHR",
                                 (PFN_xrVoidFunction *) &pfn));

    memset(&req, 0, sizeof (req));
    req.type = XR_TYPE_GRAPHICS_REQUIREMENTS_OPENGL_ES_KHR;

    XR_TRY(pfn(xr_instance, xr_system, &req));

    memset(&bind, 0, sizeof (bind));
    bind.type    = XR_TYPE_GRAPHICS_BINDING_OPENGL_ES_ANDROID_KHR;
    bind.display = dpy;
    bind.config  = cfg;
    bind.context = ctx;

    memset(&create, 0, sizeof (create));
    create.type     = XR_TYPE_SESSION_CREATE_INFO;
    create.next     = &bind;
    create.systemId = xr_system;

    XR_TRY(xrCreateSession(xr_instance, &create, &xr_session));

    /* Prefer a floor-relative origin, so the chase camera sits at a sane
     * height without having to guess the player's stature. */

    XR_TRY(xrEnumerateReferenceSpaces(xr_session, 0, &type_count, NULL));

    if (!(types = calloc(type_count, sizeof (*types))))
        return 0;

    if (XR_FAILED(xrEnumerateReferenceSpaces(xr_session, type_count,
                                             &type_count, types)))
    {
        free(types);
        return 0;
    }

