static int xr_init_swapchains(void)
{
    XrViewConfigurationView config_views[EYE_COUNT];

    uint32_t count = 0, i, j;
    int64_t *formats = NULL;
    int64_t  chosen  = 0;

    XR_TRY(xrEnumerateViewConfigurationViews(
               xr_instance, xr_system,
               XR_VIEW_CONFIGURATION_TYPE_PRIMARY_STEREO,
               0, &count, NULL));

    if (count != EYE_COUNT)
    {
        log_printf("HMD: expected %d views, runtime reports %u\n",
                   EYE_COUNT, count);
        return 0;
    }

    for (i = 0; i < EYE_COUNT; i++)
    {
        memset(&config_views[i], 0, sizeof (config_views[i]));
        config_views[i].type = XR_TYPE_VIEW_CONFIGURATION_VIEW;
    }

    XR_TRY(xrEnumerateViewConfigurationViews(
               xr_instance, xr_system,
               XR_VIEW_CONFIGURATION_TYPE_PRIMARY_STEREO,
               count, &count, config_views));

    XR_TRY(xrEnumerateSwapchainFormats(xr_session, 0, &count, NULL));

    if (!(formats = calloc(count, sizeof (*formats))))
        return 0;

    if (XR_FAILED(xrEnumerateSwapchainFormats(xr_session, count, &count,
                                              formats)))
    {
        free(formats);
        return 0;
    }

    for (i = 0; i < count; i++)
    {
        if (formats[i] == GL_SRGB8_ALPHA8)
        {
            chosen = formats[i];
            break;
        }

        if (formats[i] == GL_RGBA8 && !chosen)
            chosen = formats[i];
    }

    free(formats);

    if (!chosen)
    {
        log_printf("HMD: no usable swapchain format\n");
        return 0;
    }

    log_printf("HMD: swapchain format 0x%x\n", (unsigned) chosen);

    for (i = 0; i < EYE_COUNT; i++)
    {
        struct eye_swapchain *e = &xr_eye[i];
        XrSwapchainCreateInfo info;

        e->w = (int32_t) (config_views[i].recommendedImageRectWidth *
                          EYE_SCALE_NUM / EYE_SCALE_DEN);
        e->h = (int32_t) (config_views[i].recommendedImageRectHeight *
                          EYE_SCALE_NUM / EYE_SCALE_DEN);

        memset(&info, 0, sizeof (info));
        info.type        = XR_TYPE_SWAPCHAIN_CREATE_INFO;
        info.usageFlags  = XR_SWAPCHAIN_USAGE_COLOR_ATTACHMENT_BIT |
                           XR_SWAPCHAIN_USAGE_SAMPLED_BIT;
        info.format      = chosen;
        info.sampleCount = 1;
        info.width       = (uint32_t) e->w;
        info.height      = (uint32_t) e->h;
        info.faceCount   = 1;
        info.arraySize   = 1;
        info.mipCount    = 1;

        XR_TRY(xrCreateSwapchain(xr_session, &info, &e->handle));

        XR_TRY(xrEnumerateSwapchainImages(e->handle, 0, &e->image_count, NULL));

        e->images = calloc(e->image_count, sizeof (*e->images));
        e->fbos   = calloc(e->image_count, sizeof (*e->fbos));

        if (!e->images || !e->fbos)
            return 0;

        for (j = 0; j < e->image_count; j++)
            e->images[j].type = XR_TYPE_SWAPCHAIN_IMAGE_OPENGL_ES_KHR;

        XR_TRY(xrEnumerateSwapchainImages(
                   e->handle, e->image_count, &e->image_count,
                   (XrSwapchainImageBaseHeader *) e->images));

        /*
         * One depth-plus-stencil buffer per eye, shared by all of that eye's
         * images, since they are rendered strictly in sequence. The stencil
         * is not optional: ball/game_draw.c:520-556 masks reflections with
         * it whenever CONFIG_REFLECTION is on.
         */

        gles_GenRenderbuffers(1, &e->depth);
        gles_BindRenderbuffer(GL_RENDERBUFFER, e->depth);
        gles_RenderbufferStorage(GL_RENDERBUFFER, GL_DEPTH24_STENCIL8,
                                 e->w, e->h);
        gles_BindRenderbuffer(GL_RENDERBUFFER, 0);

        /* The framebuffer names themselves come from gl4es, which passes
         * them straight through, so that binding one by name later leaves
         * its state tracking telling the truth. */

        glGenFramebuffers(e->image_count, e->fbos);

        for (j = 0; j < e->image_count; j++)
        {
            GLenum status;

            glBindFramebuffer(GL_FRAMEBUFFER, e->fbos[j]);

            gles_FramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0,
                                      GL_TEXTURE_2D, e->images[j].image, 0);
            gles_FramebufferRenderbuffer(GL_FRAMEBUFFER, GL_DEPTH_ATTACHMENT,
                                         GL_RENDERBUFFER, e->depth);
            gles_FramebufferRenderbuffer(GL_FRAMEBUFFER, GL_STENCIL_ATTACHMENT,
                                         GL_RENDERBUFFER, e->depth);

            status = gles_CheckFramebufferStatus(GL_FRAMEBUFFER);

            if (status != GL_FRAMEBUFFER_COMPLETE)
            {
                log_printf("HMD: eye %u image %u framebuffer incomplete "
                           "(0x%x)\n", i, j, (unsigned int) status);
                return 0;
            }
        }

        glBindFramebuffer(GL_FRAMEBUFFER, 0);

        log_printf("HMD: eye %u swapchain %dx%d of %ux%u recommended, "
                   "%u images\n", i, e->w, e->h,
                   config_views[i].recommendedImageRectWidth,
                   config_views[i].recommendedImageRectHeight,
                   e->image_count);
    }

    for (i = 0; i < EYE_COUNT; i++)
    {
        memset(&xr_views[i], 0, sizeof (xr_views[i]));
        xr_views[i].type = XR_TYPE_VIEW;
    }

    return 1;
}

