int hmd_stat(void)
{
    return xr_session != XR_NULL_HANDLE;
}

void hmd_init(void)
{
    if (!load_gles())        { hmd_free(); return; }
    if (!xr_init_loader())   { hmd_free(); return; }
    if (!xr_init_instance()) { hmd_free(); return; }
    if (!xr_init_session())  { hmd_free(); return; }

    if (!xr_init_swapchains())
    {
        hmd_free();
        return;
    }

    /*
     * From here on the render target is a swapchain image, not the window,
     * so the rest of the engine has to size itself against that. This runs
     * after video_resize() in video_mode(), which set these from the window.
     */

    video.device_w     = xr_eye[0].w;
    video.device_h     = xr_eye[0].h;
    video.device_scale = 1.0f;
}

void hmd_free(void)
{
    int i;

    for (i = 0; i < EYE_COUNT; i++)
    {
        struct eye_swapchain *e = &xr_eye[i];

        if (e->fbos)
        {
            glDeleteFramebuffers(e->image_count, e->fbos);
            free(e->fbos);
        }

        if (e->depth)
            gles_DeleteRenderbuffers(1, &e->depth);

        if (e->handle != XR_NULL_HANDLE)
            xrDestroySwapchain(e->handle);

        free(e->images);

        memset(e, 0, sizeof (*e));
    }

    if (xr_space   != XR_NULL_HANDLE) xrDestroySpace(xr_space);
    if (xr_session != XR_NULL_HANDLE) xrDestroySession(xr_session);
    if (xr_instance != XR_NULL_HANDLE) xrDestroyInstance(xr_instance);

    xr_space    = XR_NULL_HANDLE;
    xr_session  = XR_NULL_HANDLE;
    xr_instance = XR_NULL_HANDLE;
    xr_system   = XR_NULL_SYSTEM_ID;
    xr_state    = XR_SESSION_STATE_UNKNOWN;

    xr_running    = 0;
    frame_begun   = 0;
    should_render = 0;
    views_valid   = 0;
    acquired_eye  = -1;
}

/*---------------------------------------------------------------------------*/
/* Per-frame                                                                 */

static void end_frame(int layer_count)
{
    XrFrameEndInfo end;
    const XrCompositionLayerBaseHeader *layers[1];
    XrCompositionLayerProjection layer;

    if (!frame_begun)
        return;

    memset(&end, 0, sizeof (end));
    end.type                 = XR_TYPE_FRAME_END_INFO;
    end.displayTime          = xr_display_time;
    end.environmentBlendMode = XR_ENVIRONMENT_BLEND_MODE_OPAQUE;

    if (layer_count)
    {
        memset(&layer, 0, sizeof (layer));
        layer.type      = XR_TYPE_COMPOSITION_LAYER_PROJECTION;
        layer.space     = xr_space;
        layer.viewCount = EYE_COUNT;
        layer.views     = xr_layer_views;

        layers[0] = (const XrCompositionLayerBaseHeader *) &layer;

        end.layerCount = 1;
        end.layers     = layers;
    }

    xrEndFrame(xr_session, &end);

    frame_begun = 0;
}

static void poll_events(void)
{
    XrEventDataBuffer ev;

    for (;;)
    {
        memset(&ev, 0, sizeof (ev));
        ev.type = XR_TYPE_EVENT_DATA_BUFFER;

        if (xrPollEvent(xr_instance, &ev) != XR_SUCCESS)
            break;

        switch (ev.type)
        {
        case XR_TYPE_EVENT_DATA_SESSION_STATE_CHANGED:
        {
            const XrEventDataSessionStateChanged *e =
                (const XrEventDataSessionStateChanged *) &ev;

            xr_state = e->state;

            log_printf("HMD: session state %d\n", (int) xr_state);

            if (xr_state == XR_SESSION_STATE_READY)
            {
                XrSessionBeginInfo begin;

                memset(&begin, 0, sizeof (begin));
                begin.type = XR_TYPE_SESSION_BEGIN_INFO;
                begin.primaryViewConfigurationType =
                    XR_VIEW_CONFIGURATION_TYPE_PRIMARY_STEREO;

                if (XR_SUCCEEDED(xrBeginSession(xr_session, &begin)))
                    xr_running = 1;
            }
            else if (xr_state == XR_SESSION_STATE_STOPPING)
            {
                xr_running = 0;
                xrEndSession(xr_session);
            }
            else if (xr_state == XR_SESSION_STATE_EXITING ||
                     xr_state == XR_SESSION_STATE_LOSS_PENDING)
            {
                SDL_Event quit;

                xr_running = 0;

                memset(&quit, 0, sizeof (quit));
                quit.type = SDL_QUIT;
                SDL_PushEvent(&quit);
            }

            break;
        }

        case XR_TYPE_EVENT_DATA_INSTANCE_LOSS_PENDING:
        {
            SDL_Event quit;

            memset(&quit, 0, sizeof (quit));
            quit.type = SDL_QUIT;
            SDL_PushEvent(&quit);

            break;
        }

        default:
            break;
        }
    }
}

void hmd_poll(void)
{
    XrFrameWaitInfo  wait;
    XrFrameState     state;
    XrFrameBeginInfo begin;

    XrViewLocateInfo locate;
    XrViewState      view_state;
    uint32_t         view_count = EYE_COUNT;

    if (!hmd_stat())
        return;

    /*
     * A frame still open here means the caller skipped its paint after we
     * began one. Close it empty rather than leaving xrBeginFrame unbalanced.
     */

    if (frame_begun)
    {
        acquired_eye = -1;
        end_frame(0);
    }

    should_render = 0;
    views_valid   = 0;

    poll_events();

    if (!xr_running)
    {
        /* No session to pace us, so do not spin. */

        SDL_Delay(10);
        return;
    }

    memset(&wait, 0, sizeof (wait));
    wait.type = XR_TYPE_FRAME_WAIT_INFO;

    memset(&state, 0, sizeof (state));
    state.type = XR_TYPE_FRAME_STATE;

    if (XR_FAILED(xrWaitFrame(xr_session, &wait, &state)))
        return;

    xr_display_time = state.predictedDisplayTime;

    memset(&begin, 0, sizeof (begin));
    begin.type = XR_TYPE_FRAME_BEGIN_INFO;

    if (XR_FAILED(xrBeginFrame(xr_session, &begin)))
        return;

    frame_begun = 1;

    memset(&view_state, 0, sizeof (view_state));
    view_state.type = XR_TYPE_VIEW_STATE;

    memset(&locate, 0, sizeof (locate));
    locate.type                  = XR_TYPE_VIEW_LOCATE_INFO;
    locate.viewConfigurationType = XR_VIEW_CONFIGURATION_TYPE_PRIMARY_STEREO;
    locate.displayTime           = xr_display_time;
    locate.space                 = xr_space;

    if (XR_SUCCEEDED(xrLocateViews(xr_session, &locate, &view_state,
                                   EYE_COUNT, &view_count, xr_views)))
        views_valid =
            (view_state.viewStateFlags & XR_VIEW_STATE_POSITION_VALID_BIT) &&
            (view_state.viewStateFlags & XR_VIEW_STATE_ORIENTATION_VALID_BIT);

    if (state.shouldRender && views_valid)
        should_render = 1;
    else
        end_frame(0);
}

int hmd_should_render(void)
{
    return !hmd_stat() || should_render;
}

void hmd_step(void)
{
}

/*---------------------------------------------------------------------------*/

static void release_eye(void)
{
    if (acquired_eye >= 0)
    {
        XrSwapchainImageReleaseInfo rel;

        memset(&rel, 0, sizeof (rel));
        rel.type = XR_TYPE_SWAPCHAIN_IMAGE_RELEASE_INFO;

        xrReleaseSwapchainImage(xr_eye[acquired_eye].handle, &rel);

        acquired_eye = -1;
    }
}

static void prep_eye(int eye)
{
    struct eye_swapchain *e = &xr_eye[eye];

    XrSwapchainImageAcquireInfo acq;
    XrSwapchainImageWaitInfo    wait;

    cur_eye = eye;

    if (!should_render)
        return;

    release_eye();

    memset(&acq, 0, sizeof (acq));
    acq.type = XR_TYPE_SWAPCHAIN_IMAGE_ACQUIRE_INFO;

    if (XR_FAILED(xrAcquireSwapchainImage(e->handle, &acq, &acquired_index)))
        return;

    memset(&wait, 0, sizeof (wait));
    wait.type    = XR_TYPE_SWAPCHAIN_IMAGE_WAIT_INFO;
    wait.timeout = XR_INFINITE_DURATION;

    if (XR_FAILED(xrWaitSwapchainImage(e->handle, &wait)))
        return;

    acquired_eye = eye;

    glBindFramebuffer(GL_FRAMEBUFFER, e->fbos[acquired_index]);
    glViewport(0, 0, e->w, e->h);
    glScissor (0, 0, e->w, e->h);

    /* Describe what is about to be painted, for the layer at end of frame. */

    memset(&xr_layer_views[eye], 0, sizeof (xr_layer_views[eye]));
    xr_layer_views[eye].type = XR_TYPE_COMPOSITION_LAYER_PROJECTION_VIEW;
    xr_layer_views[eye].pose = xr_views[eye].pose;
    xr_layer_views[eye].fov  = xr_views[eye].fov;
    xr_layer_views[eye].subImage.swapchain               = e->handle;
    xr_layer_views[eye].subImage.imageRect.offset.x      = 0;
    xr_layer_views[eye].subImage.imageRect.offset.y      = 0;
    xr_layer_views[eye].subImage.imageRect.extent.width  = e->w;
    xr_layer_views[eye].subImage.imageRect.extent.height = e->h;
    xr_layer_views[eye].subImage.imageArrayIndex         = 0;
}

void hmd_prep_left(void)
{
    prep_eye(0);
}

void hmd_prep_right(void)
{
    prep_eye(1);
}

void hmd_swap(void)
{
    release_eye();

    glBindFramebuffer(GL_FRAMEBUFFER, 0);

    end_frame(should_render ? 1 : 0);
}

/*---------------------------------------------------------------------------*/

void hmd_persp(float n, float f)
{
    const XrFovf  *fov  = &xr_views[cur_eye].fov;
    const XrPosef *pose = &xr_views[cur_eye].pose;

    float t[4];
    float q[4];
    float p[3];

    float P[16];
    float V[16];

    t[0] = tanf(fov->angleLeft);
    t[1] = tanf(fov->angleRight);
    t[2] = tanf(fov->angleDown);
    t[3] = tanf(fov->angleUp);

    q[0] = pose->orientation.x;
    q[1] = pose->orientation.y;
    q[2] = pose->orientation.z;
    q[3] = pose->orientation.w;

    p[0] = pose->position.x;
    p[1] = pose->position.y;
    p[2] = pose->position.z;

    hmd_frustum(P, t, n, f);
    hmd_view   (V, q, p);

    glMatrixMode(GL_PROJECTION);
    glLoadMatrixf(P);

    glMatrixMode(GL_MODELVIEW);
    glLoadMatrixf(V);
}

/*
 * Place the pixel-space GUI on a world-locked quad in front of the reference
 * space origin. Head-locked panels are far less comfortable to read, and a
 * world-locked one can be looked away from.
 */

void hmd_ortho(void)
{
    const float dist   = 2.00f;   /* metres in front of the origin */
    const float height = 1.50f;   /* metres above the floor        */
    const float span   = 1.60f;   /* metres the GUI height spans   */

    const float s = span / (float) video.device_h;

    hmd_persp(0.1f, 100.0f);

    glTranslatef(0.0f, height, -dist);
    glScalef(s, s, s);
    glTranslatef(-0.5f * (float) video.device_w,
                 -0.5f * (float) video.device_h, 0.0f);
}

